std::vector<int> R1 = {1, 5, 8};
std::vector<int> R2 = {2, 4, 9};
std::vector<int> Dest(6); // Must fit R1.size + R2.size

// Merges two sorted input ranges R1, R2 into Dest.
// Uses operator< by default (stable merge).
std::merge(R1.begin(), R1.end(),
           R2.begin(), R2.end(),
           Dest.begin());

// Custom comparison predicate version
std::merge(R1.cbegin(), R1.cend(),
           R2.cbegin(), R2.cend(),
           Dest.begin(),
           std::less<int>()); // Predicate function/functor
